const projectGrid = document.getElementById("projectGrid");
const projectSearch = document.getElementById("projectSearch");
const projectStatus = document.getElementById("projectStatus");
const resetFilters = document.getElementById("resetFilters");
const filterButtons = [...document.querySelectorAll("[data-filter]")];
const shortcutButtons = [...document.querySelectorAll("[data-filter-target]")];
const projectModal = document.getElementById("projectModal");
const modalVideo = document.getElementById("modalVideo");
const modalImage = document.getElementById("modalImage");
const modalPoster = document.getElementById("modalPoster");
let activeFilter = "all";
let searchTerm = "";
let modalOpener = null;
let imageRequest = 0;

function fileNumber(project) {
  return String(projects.indexOf(project) + 1).padStart(3, "0");
}

function getFilteredProjects(filter, query) {
  const text = query.trim().toLocaleLowerCase();
  return projects.filter(project => {
    const categoryMatches = filter === "all" || project.category === filter;
    const searchable = [project.title, project.collection, project.type,
      project.description, project.contribution, ...project.tags].join(" ").toLocaleLowerCase();
    return categoryMatches && (!text || searchable.includes(text));
  });
}

function span(className, text) {
  const element = document.createElement("span");
  element.className = className;
  element.textContent = text;
  return element;
}

function createProjectRow(project) {
  const row = document.createElement("button");
  row.type = "button";
  row.className = "project-row";
  row.setAttribute("aria-label", `Open project: ${project.title}`);
  const name = document.createElement("span");
  name.append(span("project-name", project.title));
  name.append(span("project-collection", project.collection));
  row.append(span("project-file", fileNumber(project)), name,
    span("project-type", project.type), span("project-open", "Open ↗"));
  row.addEventListener("click", () => openProjectModal(project));
  return row;
}

function renderProjects() {
  const matchingProjects = getFilteredProjects(activeFilter, searchTerm);
  const content = document.createDocumentFragment();
  const isFiltered = activeFilter !== "all" || Boolean(searchTerm.trim());
  const count = matchingProjects.length;
  projectStatus.textContent = `${count} ${count === 1 ? "project" : "projects"}${isFiltered ? " found" : " in the archive"}`;
  resetFilters.hidden = !isFiltered;

  categoryInfo.forEach((category, index) => {
    const items = matchingProjects.filter(project => project.category === category.key)
      .sort((a, b) => Number(Boolean(b.featured)) - Number(Boolean(a.featured)));
    if (!items.length) return;
    const group = document.createElement("details");
    group.className = "archive-group";
    group.open = isFiltered || index === 0;
    const summary = document.createElement("summary");
    const toggle = span("group-toggle", "+");
    toggle.setAttribute("aria-hidden", "true");
    summary.append(span("group-number", String(index + 1).padStart(2, "0")),
      span("group-name", category.title),
      span("group-count", `${items.length} ${items.length === 1 ? "file" : "files"}`), toggle);
    group.append(summary);
    items.forEach(project => group.append(createProjectRow(project)));
    content.append(group);
  });

  if (!count) {
    const empty = document.createElement("div");
    empty.className = "empty-state";
    const heading = document.createElement("h3");
    heading.textContent = "No file by that name.";
    const description = document.createElement("p");
    description.textContent = "Try another title, subject or skill, or reset the filters to see every project.";
    empty.append(heading, description);
    content.append(empty);
  }
  projectGrid.replaceChildren(content);
}

function setFilter(filter, clearSearch = false) {
  activeFilter = filter;
  if (clearSearch) {
    searchTerm = "";
    projectSearch.value = "";
  }
  filterButtons.forEach(button => {
    button.setAttribute("aria-pressed", String(button.dataset.filter === filter));
  });
  shortcutButtons.forEach(button => {
    button.classList.toggle("is-active", button.dataset.filterTarget === filter);
  });
  renderProjects();
}

filterButtons.forEach(button => {
  button.addEventListener("click", () => setFilter(button.dataset.filter));
});
shortcutButtons.forEach(button => {
  button.addEventListener("click", () => {
    setFilter(button.dataset.filterTarget, true);
    document.getElementById("archiveTools").scrollIntoView({ block: "start" });
  });
});
projectSearch.addEventListener("input", () => {
  searchTerm = projectSearch.value;
  renderProjects();
});
resetFilters.addEventListener("click", () => {
  setFilter("all", true);
  projectSearch.focus({ preventScroll: true });
});
document.querySelectorAll("[data-total-projects]").forEach(element => {
  element.textContent = projects.length;
});

// Native dialog provides keyboard focus containment and Escape-to-close.
function getProjectImage(project) {
  if (project.title === "Digestion Expedition") return projectStills.digestion;
  if (project.collection === "Fun Factory") return projectStills["fun-factory"];
  if (project.title === featuredProjects[2].projectTitle) return projectStills.vr;
  return project.image || "";
}

function watchUrl(embedUrl) {
  const url = new URL(embedUrl);
  const id = url.pathname.split("/").filter(Boolean).pop();
  return `https://www.youtube.com/watch?v=${encodeURIComponent(id)}`;
}

function openProjectModal(project) {
  if (!project) return;
  modalOpener = document.activeElement;
  const thisRequest = ++imageRequest;
  document.getElementById("modalFile").textContent = `THE SHOUN FILES / ${fileNumber(project)}`;
  document.getElementById("modalCollection").textContent = project.collection;
  document.getElementById("modalVisualTitle").textContent = project.title;
  document.getElementById("modalType").textContent = project.type;
  document.getElementById("modalTitle").textContent = project.title;
  document.getElementById("modalDescription").textContent = project.description;
  document.getElementById("modalContribution").textContent = project.contribution;
  const tags = document.getElementById("modalTags");
  tags.replaceChildren(...project.tags.map(tag => span("", tag)));
  modalImage.hidden = true;
  modalImage.removeAttribute("src");
  modalPoster.hidden = false;

  const source = getProjectImage(project);
  if (source) {
    const loadingImage = new Image();
    loadingImage.onload = () => {
      if (thisRequest !== imageRequest || !projectModal.open) return;
      modalImage.src = source;
      modalImage.alt = `${project.collection} — project image`;
      modalImage.hidden = false;
      modalPoster.hidden = true;
    };
    // Missing optional legacy thumbnails retain the readable project title panel.
    loadingImage.onerror = () => {};
    loadingImage.src = source;
  }

  const videoContainer = document.getElementById("modalVideoContainer");
  const watchLink = document.getElementById("modalWatchLink");
  const hasVideo = Boolean(project.video);
  videoContainer.hidden = !hasVideo;
  watchLink.hidden = !hasVideo;
  modalVideo.removeAttribute("src");
  if (hasVideo) {
    modalVideo.title = `${project.title} — project demonstration`;
    modalVideo.src = project.video;
    watchLink.href = watchUrl(project.video);
  } else {
    watchLink.removeAttribute("href");
  }
  if (!projectModal.open) projectModal.showModal();
  document.body.classList.add("modal-open");
  projectModal.scrollTop = 0;
  document.getElementById("modalClose").focus({ preventScroll: true });
}

function closeProjectModal() {
  projectModal.close();
}

document.getElementById("modalClose").addEventListener("click", closeProjectModal);
document.getElementById("modalDoneButton").addEventListener("click", closeProjectModal);
projectModal.addEventListener("close", () => {
  imageRequest++;
  modalVideo.removeAttribute("src");
  modalImage.removeAttribute("src");
  document.body.classList.remove("modal-open");
  if (modalOpener && modalOpener.isConnected) modalOpener.focus({ preventScroll: true });
});
projectModal.addEventListener("click", event => {
  if (event.target !== projectModal) return;
  const rect = projectModal.getBoundingClientRect();
  if (event.clientX < rect.left || event.clientX > rect.right ||
      event.clientY < rect.top || event.clientY > rect.bottom) closeProjectModal();
});

const featureTabs = [...document.querySelectorAll("[data-feature]")];
const featuredOpen = document.getElementById("featuredOpen");
function selectFeature(index, focus = false) {
  const selected = featuredProjects[index];
  const project = projects.find(item => item.title === selected.projectTitle);
  featureTabs.forEach((tab, tabIndex) => {
    const active = tabIndex === index;
    tab.setAttribute("aria-selected", String(active));
    tab.tabIndex = active ? 0 : -1;
  });
  document.getElementById("featuredPanel").setAttribute("aria-labelledby", featureTabs[index].id);
  const image = document.getElementById("featuredImage");
  image.src = projectStills[selected.image];
  image.alt = selected.alt;
  document.getElementById("featuredCategory").textContent = selected.category;
  document.getElementById("featuredNumber").textContent = `${String(index + 1).padStart(2, "0")}—03`;
  document.getElementById("featuredFile").textContent = `FILE / ${fileNumber(project)}`;
  const title = document.getElementById("featuredTitle");
  const lines = selected.title.split("\n");
  title.replaceChildren();
  lines.forEach((line, lineIndex) => {
    if (lineIndex) title.append(document.createElement("br"));
    title.append(document.createTextNode(line + (lineIndex < lines.length - 1 ? " " : "")));
  });
  document.getElementById("featuredDescription").textContent = selected.description;
  featuredOpen.dataset.projectTitle = selected.projectTitle;
  featuredOpen.setAttribute("aria-label", `Open ${selected.title.replace(/\n/g, " ").replace(/\.$/, "")} project`);
  if (focus) featureTabs[index].focus({ preventScroll: true });
}
featureTabs.forEach((tab, index) => {
  tab.addEventListener("click", () => selectFeature(index));
  tab.addEventListener("keydown", event => {
    let target = index;
    if (event.key === "ArrowRight") target = (index + 1) % featureTabs.length;
    else if (event.key === "ArrowLeft") target = (index - 1 + featureTabs.length) % featureTabs.length;
    else if (event.key === "Home") target = 0;
    else if (event.key === "End") target = featureTabs.length - 1;
    else return;
    event.preventDefault();
    selectFeature(target, true);
  });
});
featuredOpen.addEventListener("click", () => {
  openProjectModal(projects.find(project => project.title === featuredOpen.dataset.projectTitle));
});

// Navigation and the original developer-details disclosure.
const menuButton = document.getElementById("menuButton");
const siteNav = document.getElementById("siteNav");
function closeMenu() {
  siteNav.classList.remove("is-open");
  menuButton.setAttribute("aria-expanded", "false");
  menuButton.querySelector("span").textContent = "+";
}
menuButton.addEventListener("click", () => {
  const open = menuButton.getAttribute("aria-expanded") !== "true";
  siteNav.classList.toggle("is-open", open);
  menuButton.setAttribute("aria-expanded", String(open));
  menuButton.querySelector("span").textContent = open ? "−" : "+";
});
siteNav.querySelectorAll("a").forEach(link => {
  link.addEventListener("click", closeMenu);
});
document.addEventListener("keydown", event => {
  if (event.key === "Escape" && siteNav.classList.contains("is-open") && !projectModal.open) {
    closeMenu();
    menuButton.focus();
  }
});
document.addEventListener("click", event => {
  if (!siteNav.contains(event.target) && !menuButton.contains(event.target)) closeMenu();
});
const devModeButton = document.getElementById("devModeButton");
const devSection = document.getElementById("devSection");
devModeButton.addEventListener("click", () => {
  const expanded = devModeButton.getAttribute("aria-expanded") !== "true";
  devModeButton.setAttribute("aria-expanded", String(expanded));
  devModeButton.querySelector("span").textContent = expanded ? "−" : "+";
  devSection.hidden = !expanded;
  if (expanded) devSection.scrollIntoView({ block: "nearest" });
});

renderProjects();
selectFeature(0);
